-- Generated by Murakumo: load open_meteo.weather_hourly (incremental), without Murakumo. Run it from the project folder.

-- The files under landing/open_meteo/weather_hourly/ that were not loaded before.
create or replace temp table new_rows as
select cast(location_key as VARCHAR) as location_key, cast(latitude as DECIMAL(9,6)) as latitude, cast(longitude as DECIMAL(9,6)) as longitude, cast(timezone as VARCHAR) as timezone, cast(observed_at as TIMESTAMP) as observed_at, cast(temperature_2m as DECIMAL(5,1)) as temperature_2m, cast(relative_humidity_2m as INTEGER) as relative_humidity_2m, cast(precipitation as DECIMAL(6,1)) as precipitation, cast(rain as DECIMAL(6,1)) as rain, cast(snowfall as DECIMAL(6,2)) as snowfall, cast(snow_depth as DECIMAL(6,2)) as snow_depth, cast(weather_code as INTEGER) as weather_code, cast(cloud_cover as INTEGER) as cloud_cover, cast(wind_speed_10m as DECIMAL(5,1)) as wind_speed_10m, cast(wind_gusts_10m as DECIMAL(5,1)) as wind_gusts_10m, filename
from read_json('landing/open_meteo/weather_hourly/weather_hourly_*.jsonl', format = 'newline_delimited', filename = true, columns = {'location_key': 'VARCHAR', 'latitude': 'DECIMAL(9,6)', 'longitude': 'DECIMAL(9,6)', 'timezone': 'VARCHAR', 'observed_at': 'TIMESTAMP', 'temperature_2m': 'DECIMAL(5,1)', 'relative_humidity_2m': 'INTEGER', 'precipitation': 'DECIMAL(6,1)', 'rain': 'DECIMAL(6,1)', 'snowfall': 'DECIMAL(6,2)', 'snow_depth': 'DECIMAL(6,2)', 'weather_code': 'INTEGER', 'cloud_cover': 'INTEGER', 'wind_speed_10m': 'DECIMAL(5,1)', 'wind_gusts_10m': 'DECIMAL(5,1)'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'weather_hourly');
-- Incremental: the new rows replace the rows with the same key; the latest of each key is kept.
delete from raw_open_meteo.weather_hourly where (location_key, observed_at) in (select location_key, observed_at from new_rows);
insert into raw_open_meteo.weather_hourly (location_key, latitude, longitude, timezone, observed_at, temperature_2m, relative_humidity_2m, precipitation, rain, snowfall, snow_depth, weather_code, cloud_cover, wind_speed_10m, wind_gusts_10m, _ingested_at, _batch_id)
select location_key, latitude, longitude, timezone, observed_at, temperature_2m, relative_humidity_2m, precipitation, rain, snowfall, snow_depth, weather_code, cloud_cover, wind_speed_10m, wind_gusts_10m, now(), parse_filename(filename) from new_rows
qualify row_number() over (partition by location_key, observed_at order by observed_at desc nulls last) = 1;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'weather_hourly', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
